<script setup lang="ts">import {computed} from 'vue';import type {Result} from '../types/domain';import {number} from '../utils/format';const props=defineProps<{result:Partial<Result>;kind:'deming'|'ba'}>();const points=computed(()=>props.result.points||[]);const bounds=computed(()=>{const r=props.result;const xs=points.value.map(p=>props.kind==='deming'?p.x:p.mean);const ys=points.value.map(p=>props.kind==='deming'?p.y:p.diff);if(props.kind==='deming'){ys.push(...xs,...xs.map(x=>(r.intercept||0)+(r.slope||1)*x));}else{ys.push(0,-(r.config?.allowance||0),r.config?.allowance||0,...(r.lower_ci||[]),...(r.upper_ci||[]));}let minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys);const px=Math.max((maxx-minx)*.06,.1),py=Math.max((maxy-miny)*.12,.2);return {minx:minx-px,maxx:maxx+px,miny:miny-py,maxy:maxy+py};});const sx=(x:number)=>62+(x-bounds.value.minx)/(bounds.value.maxx-bounds.value.minx)*496;const sy=(y:number)=>260-(y-bounds.value.miny)/(bounds.value.maxy-bounds.value.miny)*218;const ticks=[0,.25,.5,.75,1];</script><template><section class="agreement-plot"><div class="plot-heading"><h3>{{kind==='deming'?'双侧误差回归':'差值与一致性'}}</h3><span>{{kind==='deming'?'DEMING / Y = a + bX':'BLAND–ALTMAN / Y − X'}}</span></div><svg v-if="points.length" viewBox="0 0 600 310" role="img" :aria-label="kind==='deming'?'Deming回归与原始配对测量散点':'Bland Altman差值与一致性界限散点'"><g v-for="t in ticks" :key="t" class="plot-grid"><line x1="62" x2="558" :y1="42+t*218" :y2="42+t*218"/><line :x1="62+t*496" :x2="62+t*496" y1="42" y2="260"/><text x="51" :y="46+t*218" text-anchor="end">{{number(bounds.maxy-t*(bounds.maxy-bounds.miny),1)}}</text><text :x="62+t*496" y="280" text-anchor="middle">{{number(bounds.minx+t*(bounds.maxx-bounds.minx),1)}}</text></g><template v-if="kind==='deming'"><line class="identity-line" :x1="sx(result.x_range![0])" :x2="sx(result.x_range![1])" :y1="sy(result.x_range![0])" :y2="sy(result.x_range![1])"/><line class="fit-line" :x1="sx(result.x_range![0])" :x2="sx(result.x_range![1])" :y1="sy(result.intercept!+result.slope!*result.x_range![0])" :y2="sy(result.intercept!+result.slope!*result.x_range![1])"/></template><template v-else><rect class="confidence-band" x="62" width="496" :y="sy(result.lower_ci![1])" :height="sy(result.lower_ci![0])-sy(result.lower_ci![1])"/><rect class="confidence-band" x="62" width="496" :y="sy(result.upper_ci![1])" :height="sy(result.upper_ci![0])-sy(result.upper_ci![1])"/><line class="zero-line" x1="62" x2="558" :y1="sy(0)" :y2="sy(0)"/><line v-for="line in [result.loa_lower!,result.loa_upper!]" :key="line" class="limit-line" x1="62" x2="558" :y1="sy(line)" :y2="sy(line)"/><line class="fit-line" x1="62" x2="558" :y1="sy(result.bias!)" :y2="sy(result.bias!)"/><line v-for="line in [-result.config!.allowance,result.config!.allowance]" :key="line" class="allowance-line" x1="62" x2="558" :y1="sy(line)" :y2="sy(line)"/></template><circle v-for="p in points" :key="p.code" :cx="sx(kind==='deming'?p.x:p.mean)" :cy="sy(kind==='deming'?p.y:p.diff)" r="2.4" class="measurement-point"><title>{{p.code}} / X {{p.x}} / Y {{p.y}}</title></circle><text x="62" y="20" class="axis-title">{{kind==='deming'?'候选仪器 Y / %':'差值 Y−X / 百分点'}}</text><text x="558" y="303" text-anchor="end" class="axis-title">{{kind==='deming'?'参考仪器 X / %':'两仪器均值 / %'}}</text></svg><div class="plot-legend" v-if="kind==='deming'"><span class="green">— Deming 拟合</span><span class="plum">┄ 原值相等 Y=X</span><span>λ={{result.config?.lambda_ratio}}（Y误差方差 / X误差方差）</span></div><div class="plot-legend" v-else><span class="green">— 平均偏差</span><span class="plum">— 一致性界限 / 阴影95%CI</span><span>┄ 允许误差 ±{{result.config?.allowance}}</span></div></section></template>
